-- =====================================================================
-- life-dashboard — PostgreSQL baseline schema
--
-- Equivalent to the final state of the legacy SQLite/MySQL migrations
-- 001–042 in src/DB/Schema.php (personal-dashboard, Sept 2026).
--
-- Type mapping from the legacy schema:
--   INTEGER PK AUTOINCREMENT -> BIGINT GENERATED BY DEFAULT AS IDENTITY
--                               (BY DEFAULT so the SQLite importer can keep ids)
--   TINYINT(1)               -> SMALLINT  (app code compares with 0/1, not booleans)
--   DATETIME                 -> TIMESTAMP(0) without time zone, stored as UTC
--                               (matches SQLite CURRENT_TIMESTAMP semantics)
--   REAL                     -> DOUBLE PRECISION
--   size_bytes INTEGER       -> BIGINT (cloud objects can exceed 2 GiB)
--
-- Runs inside one transaction (see Schema::runPgsqlPending()).
-- =====================================================================

CREATE TABLE users (
    id             BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    username       VARCHAR(64)  NOT NULL UNIQUE,
    email          VARCHAR(255) NOT NULL UNIQUE,
    password_hash  VARCHAR(255) NOT NULL,
    is_admin       SMALLINT     NOT NULL DEFAULT 0,
    created_at     TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    last_login_at  TIMESTAMP(0),
    last_active_at TIMESTAMP(0)
);

CREATE TABLE autologin_tokens (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id      BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    token        VARCHAR(64)  NOT NULL UNIQUE,
    label        VARCHAR(128),
    expires_at   TIMESTAMP(0),
    last_used_at TIMESTAMP(0),
    created_at   TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    revoked      SMALLINT     NOT NULL DEFAULT 0
);

CREATE TABLE user_preferences (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    pref_key   VARCHAR(64)  NOT NULL,
    pref_value TEXT,
    updated_at TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (user_id, pref_key)
);

CREATE TABLE bookmark_folders (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id    BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name       VARCHAR(128) NOT NULL,
    icon       VARCHAR(64),
    sort_order INTEGER      NOT NULL DEFAULT 0,
    created_at TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE bookmarks (
    id          BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id     BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    folder_id   BIGINT       REFERENCES bookmark_folders(id) ON DELETE SET NULL,
    title       VARCHAR(255) NOT NULL,
    url         TEXT         NOT NULL,
    favicon_url TEXT,
    sort_order  INTEGER      NOT NULL DEFAULT 0,
    created_at  TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    favicon_ext VARCHAR(8)
);

CREATE TABLE feed_sources (
    id         BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    slug       VARCHAR(64)  NOT NULL UNIQUE,
    name       VARCHAR(128) NOT NULL,
    url        TEXT         NOT NULL,
    category   VARCHAR(64),
    is_default SMALLINT     NOT NULL DEFAULT 1,
    sort_order INTEGER      NOT NULL DEFAULT 0,
    created_at TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    user_id    BIGINT       REFERENCES users(id) ON DELETE CASCADE
);
CREATE INDEX idx_feed_sources_user_id ON feed_sources(user_id);

CREATE TABLE user_feeds (
    id        BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id   BIGINT   NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    source_id BIGINT   NOT NULL REFERENCES feed_sources(id) ON DELETE CASCADE,
    enabled   SMALLINT NOT NULL DEFAULT 1,
    UNIQUE (user_id, source_id)
);

CREATE TABLE feed_cache (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    source_id    BIGINT       NOT NULL REFERENCES feed_sources(id) ON DELETE CASCADE,
    title        TEXT         NOT NULL,
    url          TEXT         NOT NULL,
    description  TEXT,
    published_at TIMESTAMP(0),
    fetched_at   TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE user_clipboards (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name             VARCHAR(128) NOT NULL,
    slug             VARCHAR(64)  NOT NULL,
    content          TEXT         NOT NULL DEFAULT '',
    content_version  INTEGER      NOT NULL DEFAULT 1,
    pin_to_dashboard SMALLINT     NOT NULL DEFAULT 0,
    auto_save        SMALLINT     NOT NULL DEFAULT 1,
    sort_order       INTEGER      NOT NULL DEFAULT 0,
    created_at       TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    updated_at       TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (user_id, slug)
);

CREATE TABLE user_flight_watches (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    ident           VARCHAR(16)  NOT NULL,
    departure_at    TIMESTAMP(0) NOT NULL,
    arrival_at      TIMESTAMP(0),
    origin_icao     VARCHAR(8),
    dest_icao       VARCHAR(8),
    icao24          VARCHAR(8),
    is_active       SMALLINT     NOT NULL DEFAULT 1,
    is_complete     SMALLINT     NOT NULL DEFAULT 0,
    sort_order      INTEGER      NOT NULL DEFAULT 0,
    status_label    VARCHAR(64),
    airborne        SMALLINT,
    latitude        DOUBLE PRECISION,
    longitude       DOUBLE PRECISION,
    altitude_m      DOUBLE PRECISION,
    velocity_ms     DOUBLE PRECISION,
    heading         DOUBLE PRECISION,
    origin_display  VARCHAR(16),
    dest_display    VARCHAR(16),
    raw_json        TEXT,
    last_checked_at TIMESTAMP(0),
    created_at      TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    completed_at    TIMESTAMP(0)
);
CREATE INDEX idx_user_flight_watches_completed_at ON user_flight_watches(completed_at);

CREATE TABLE user_ping_targets (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id         BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    label           VARCHAR(128) NOT NULL,
    target          VARCHAR(255) NOT NULL,
    sort_order      INTEGER      NOT NULL DEFAULT 0,
    is_active       SMALLINT     NOT NULL DEFAULT 1,
    is_up           SMALLINT,
    latency_ms      INTEGER,
    status_message  VARCHAR(255),
    last_checked_at TIMESTAMP(0),
    created_at      TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE user_stock_symbols (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    symbol           VARCHAR(16)  NOT NULL,
    sort_order       INTEGER      NOT NULL DEFAULT 0,
    is_active        SMALLINT     NOT NULL DEFAULT 1,
    price            DOUBLE PRECISION,
    change_amount    DOUBLE PRECISION,
    change_percent   DOUBLE PRECISION,
    last_refreshed   TIMESTAMP(0),
    raw_json         TEXT,
    created_at       TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    pin_to_dashboard SMALLINT     NOT NULL DEFAULT 0,
    UNIQUE (user_id, symbol)
);

CREATE TABLE clipboard_share_links (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clipboard_id BIGINT       NOT NULL REFERENCES user_clipboards(id) ON DELETE CASCADE,
    token        VARCHAR(12)  NOT NULL UNIQUE,
    permission   VARCHAR(8)   NOT NULL DEFAULT 'read',
    label        VARCHAR(128),
    expires_at   TIMESTAMP(0),
    revoked      SMALLINT     NOT NULL DEFAULT 0,
    last_used_at TIMESTAMP(0),
    created_at   TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE clipboard_user_shares (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    clipboard_id        BIGINT       NOT NULL REFERENCES user_clipboards(id) ON DELETE CASCADE,
    owner_user_id       BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    shared_with_user_id BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    permission          VARCHAR(8)   NOT NULL DEFAULT 'read',
    created_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (clipboard_id, shared_with_user_id)
);

CREATE TABLE user_package_watches (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id               BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    tracking_number       VARCHAR(64)  NOT NULL,
    carrier               VARCHAR(16)  NOT NULL DEFAULT 'auto',
    label                 VARCHAR(128),
    external_url          VARCHAR(512),
    is_active             SMALLINT     NOT NULL DEFAULT 1,
    is_complete           SMALLINT     NOT NULL DEFAULT 0,
    sort_order            INTEGER      NOT NULL DEFAULT 0,
    status_label          VARCHAR(64),
    status_detail         VARCHAR(255),
    estimated_delivery_at TIMESTAMP(0),
    last_event_at         TIMESTAMP(0),
    last_checked_at       TIMESTAMP(0),
    completed_at          TIMESTAMP(0),
    raw_json              TEXT,
    created_at            TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE alarm_sounds (
    id          VARCHAR(32)  NOT NULL PRIMARY KEY,
    label       VARCHAR(128) NOT NULL,
    file_ext    VARCHAR(8)   NOT NULL,
    uploaded_by BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at  TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE user_files (
    id            BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id       BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    original_name VARCHAR(255) NOT NULL,
    storage_id    VARCHAR(32)  NOT NULL UNIQUE,
    mime_type     VARCHAR(128) NOT NULL,
    ext           VARCHAR(16)  NOT NULL,
    size_bytes    BIGINT       NOT NULL,
    created_at    TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    updated_at    TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE file_share_links (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    file_id      BIGINT       NOT NULL REFERENCES user_files(id) ON DELETE CASCADE,
    token        VARCHAR(12)  NOT NULL UNIQUE,
    label        VARCHAR(128),
    expires_at   TIMESTAMP(0),
    revoked      SMALLINT     NOT NULL DEFAULT 0,
    last_used_at TIMESTAMP(0),
    created_at   TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE file_user_shares (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    file_id             BIGINT       NOT NULL REFERENCES user_files(id) ON DELETE CASCADE,
    owner_user_id       BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    shared_with_user_id BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (file_id, shared_with_user_id)
);

CREATE TABLE user_storage_connections (
    id                    BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id               BIGINT       NOT NULL UNIQUE REFERENCES users(id) ON DELETE CASCADE,
    provider              VARCHAR(32)  NOT NULL,
    credentials_encrypted TEXT         NOT NULL,
    root_provider_path    VARCHAR(512) NOT NULL,
    root_provider_id      VARCHAR(128) NOT NULL,
    is_active             SMALLINT     NOT NULL DEFAULT 1,
    connected_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    disconnected_at       TIMESTAMP(0),
    migration_dismissed   SMALLINT     NOT NULL DEFAULT 0
);

CREATE TABLE user_storage_nodes (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    connection_id    BIGINT       NOT NULL REFERENCES user_storage_connections(id) ON DELETE CASCADE,
    node_type        VARCHAR(8)   NOT NULL,
    name             VARCHAR(255) NOT NULL,
    provider_node_id VARCHAR(128) NOT NULL,
    provider_path    VARCHAR(512) NOT NULL,
    mime_type        VARCHAR(128),
    size_bytes       BIGINT,
    ext              VARCHAR(16),
    created_at       TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    updated_at       TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (connection_id, provider_path)
);

CREATE TABLE storage_node_share_links (
    id              BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    storage_node_id BIGINT       NOT NULL REFERENCES user_storage_nodes(id) ON DELETE CASCADE,
    token           VARCHAR(12)  NOT NULL UNIQUE,
    label           VARCHAR(128),
    expires_at      TIMESTAMP(0),
    revoked         SMALLINT     NOT NULL DEFAULT 0,
    last_used_at    TIMESTAMP(0),
    created_at      TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC')
);

CREATE TABLE storage_node_user_shares (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    storage_node_id     BIGINT       NOT NULL REFERENCES user_storage_nodes(id) ON DELETE CASCADE,
    owner_user_id       BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    shared_with_user_id BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    created_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (storage_node_id, shared_with_user_id)
);

CREATE TABLE system_settings (
    id                 BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    setting_key        VARCHAR(64)  NOT NULL UNIQUE,
    value_encrypted    TEXT         NOT NULL,
    updated_at         TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    updated_by_user_id BIGINT       REFERENCES users(id) ON DELETE SET NULL
);

CREATE TABLE user_todo_lists (
    id               BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id          BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name             VARCHAR(128) NOT NULL,
    slug             VARCHAR(64)  NOT NULL,
    sort_order       INTEGER      NOT NULL DEFAULT 0,
    pin_to_dashboard SMALLINT     NOT NULL DEFAULT 0,
    created_at       TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    updated_at       TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (user_id, slug)
);

CREATE TABLE user_todo_items (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    list_id             BIGINT       NOT NULL REFERENCES user_todo_lists(id) ON DELETE CASCADE,
    title               VARCHAR(255) NOT NULL,
    notes               TEXT,
    links_json          TEXT,
    status              VARCHAR(16)  NOT NULL DEFAULT 'open',
    assigned_to_user_id BIGINT       REFERENCES users(id) ON DELETE SET NULL,
    assigned_by_user_id BIGINT       REFERENCES users(id) ON DELETE SET NULL,
    created_by_user_id  BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    sort_order          INTEGER      NOT NULL DEFAULT 0,
    completed_at        TIMESTAMP(0),
    archived_at         TIMESTAMP(0),
    created_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    updated_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    due_date            DATE
);

CREATE TABLE todo_list_user_shares (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    list_id             BIGINT       NOT NULL REFERENCES user_todo_lists(id) ON DELETE CASCADE,
    owner_user_id       BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    shared_with_user_id BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    permission          VARCHAR(8)   NOT NULL DEFAULT 'read',
    created_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (list_id, shared_with_user_id)
);

CREATE TABLE user_cloudpad_canvases (
    id                   BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    user_id              BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    name                 VARCHAR(128) NOT NULL,
    slug                 VARCHAR(128) NOT NULL,
    content              TEXT         NOT NULL DEFAULT '',
    content_version      INTEGER      NOT NULL DEFAULT 1,
    control_user_id      BIGINT       REFERENCES users(id) ON DELETE SET NULL,
    control_granted_at   TIMESTAMP(0),
    control_expires_at   TIMESTAMP(0),
    control_requested_by BIGINT       REFERENCES users(id) ON DELETE SET NULL,
    control_requested_at TIMESTAMP(0),
    created_at           TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    updated_at           TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (user_id, slug)
);

CREATE TABLE cloudpad_share_links (
    id           BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    canvas_id    BIGINT       NOT NULL REFERENCES user_cloudpad_canvases(id) ON DELETE CASCADE,
    token        VARCHAR(12)  NOT NULL UNIQUE,
    permission   VARCHAR(8)   NOT NULL DEFAULT 'read',
    label        VARCHAR(128),
    expires_at   TIMESTAMP(0),
    revoked      SMALLINT     NOT NULL DEFAULT 0,
    created_at   TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    last_used_at TIMESTAMP(0)
);

CREATE TABLE cloudpad_user_shares (
    id                  BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    canvas_id           BIGINT       NOT NULL REFERENCES user_cloudpad_canvases(id) ON DELETE CASCADE,
    owner_user_id       BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    shared_with_user_id BIGINT       NOT NULL REFERENCES users(id) ON DELETE CASCADE,
    permission          VARCHAR(8)   NOT NULL DEFAULT 'read',
    created_at          TIMESTAMP(0) NOT NULL DEFAULT (now() AT TIME ZONE 'UTC'),
    UNIQUE (canvas_id, shared_with_user_id)
);
